/** Page checks in registration order (sorted by id): within a severity, findings follow this order. */
export const PAGE_CHECKS = [
  aiCrawlersBlocked,
  canonicalElsewhere,
  canonicalMissing,
  feedBroken,
  feedInvalid,
  feedOversized,
  hostDuplicate,
  llmsTxtBrokenLinks,
  llmsTxtStaleFacts,
  noindex,
  quotableFactsDisagree,
  redirectChain,
  robotsBlock,
  sitemapDead,
  sitemapHost,
  sitemapMissing,
  sitemapRedirects,
  thinHtml,
] as const;
// checks:end

export function createPageRegistry(): CheckRegistry {
  const registry = new CheckRegistry();
  for (const check of PAGE_CHECKS) registry.register(check);
  return registry;
}

